<span class="line"><span style="color:#E5C07B;">    server</span><span style="color:#ABB2BF;">.</span><span style="color:#E06C75;">dirty_before_bgsave</span><span style="color:#C678DD;"> =</span><span style="color:#E5C07B;"> server</span><span style="color:#ABB2BF;">.</span><span style="color:#E06C75;">dirty</span><span style="color:#ABB2BF;">;</span></span>
